/**
 * Perplexity API client.
 *
 * Perplexity exposes an OpenAI-compatible chat completions endpoint at
 * https://api.perplexity.ai/chat/completions. Each response carries a
 * top-level `citations` array (URLs) and optionally `search_results`
 * ({ title, url, date }) with richer metadata.
 *
 * Pro plan models: sonar, sonar-pro (default), sonar-reasoning,
 * sonar-reasoning-pro, sonar-deep-research.
 */

const PERPLEXITY_ENDPOINT = "https://api.perplexity.ai/chat/completions";

export interface PerplexitySource {
	title: string;
	url: string;
}

export interface PerplexityMessage {
	role: "system" | "user" | "assistant";
	content: string;
}

export interface PerplexityResult {
	content: string;
	citations: PerplexitySource[];
}

export interface PerplexityModelInfo {
	id: string;
	label: string;
	deepResearch: boolean;
}

/**
 * Models offered on the Perplexity Pro plan. `deepResearch` models are slow
 * (1-3 min) but produce long, heavily-cited syntheses.
 */
export const PERPLEXITY_MODELS: PerplexityModelInfo[] = [
	{ id: "sonar", label: "sonar", deepResearch: false },
	{ id: "sonar-pro", label: "sonar-pro", deepResearch: false },
	{ id: "sonar-reasoning", label: "sonar-reasoning", deepResearch: false },
	{ id: "sonar-reasoning-pro", label: "sonar-reasoning-pro", deepResearch: false },
	{ id: "sonar-deep-research", label: "sonar-deep-research", deepResearch: true },
];

export function getPerplexityApiKey(): string {
	const key = process.env.PERPLEXITY_API_KEY;
	if (!key) {
		throw new Error(
			"PERPLEXITY_API_KEY is not set. Add it to your environment (e.g. shell rc or .env).",
		);
	}
	return key;
}

function mergeSources(
	citations: unknown,
	searchResults: unknown,
): PerplexitySource[] {
	const byUrl = new Map<string, PerplexitySource>();

	if (Array.isArray(searchResults)) {
		for (const r of searchResults) {
			if (r && typeof r === "object") {
				const url = String((r as { url?: unknown }).url ?? "").trim();
				if (!url) continue;
				const title = String((r as { title?: unknown }).title ?? url);
				byUrl.set(url, { title: title || url, url });
			}
		}
	}

	if (Array.isArray(citations)) {
		for (const c of citations) {
			if (typeof c === "string") {
				const url = c.trim();
				if (url && !byUrl.has(url)) byUrl.set(url, { title: url, url });
			} else if (c && typeof c === "object") {
				const url = String((c as { url?: unknown }).url ?? "").trim();
				if (!url) continue;
				const title = String((c as { title?: unknown }).title ?? url);
				if (!byUrl.has(url)) byUrl.set(url, { title: title || url, url });
			}
		}
	}

	return Array.from(byUrl.values());
}

interface ChatCompletionChunk {
	choices?: Array<{ delta?: { content?: string | null }; message?: { content?: string } }>;
	citations?: unknown;
	search_results?: unknown;
}

/**
 * Non-streaming search. Used by the `perplexity_search` tool.
 */
export async function searchPerplexity(
	messages: PerplexityMessage[],
	model: string,
	options: { signal?: AbortSignal; maxTokens?: number } = {},
): Promise<PerplexityResult> {
	const apiKey = getPerplexityApiKey();
	const res = await fetch(PERPLEXITY_ENDPOINT, {
		method: "POST",
		headers: {
			Authorization: `Bearer ${apiKey}`,
			"Content-Type": "application/json",
			Accept: "application/json",
		},
		body: JSON.stringify({
			model,
			messages,
			stream: false,
			...(options.maxTokens ? { max_tokens: options.maxTokens } : {}),
		}),
		signal: options.signal,
	});

	if (!res.ok) {
		const text = await res.text().catch(() => "");
		throw new Error(`Perplexity API ${res.status}: ${text || res.statusText}`);
	}

	const data = (await res.json()) as ChatCompletionChunk;
	const content = data.choices?.[0]?.message?.content ?? "";
	return { content, citations: mergeSources(data.citations, data.search_results) };
}

export interface StreamCallbacks {
	onDelta?: (chunk: string) => void;
	onCitations?: (sources: PerplexitySource[]) => void;
}

/**
 * Streaming search. Calls `onDelta` for each content chunk as it arrives and
 * `onCitations` whenever the API publishes sources. Returns the final result.
 */
export async function streamPerplexity(
	messages: PerplexityMessage[],
	model: string,
	options: { signal?: AbortSignal; maxTokens?: number } & StreamCallbacks = {},
): Promise<PerplexityResult> {
	const apiKey = getPerplexityApiKey();
	const res = await fetch(PERPLEXITY_ENDPOINT, {
		method: "POST",
		headers: {
			Authorization: `Bearer ${apiKey}`,
			"Content-Type": "application/json",
			Accept: "text/event-stream",
		},
		body: JSON.stringify({
			model,
			messages,
			stream: true,
			...(options.maxTokens ? { max_tokens: options.maxTokens } : {}),
		}),
		signal: options.signal,
	});

	if (!res.ok || !res.body) {
		const text = await res.text().catch(() => "");
		throw new Error(`Perplexity API ${res.status}: ${text || res.statusText}`);
	}

	let content = "";
	let citations: PerplexitySource[] = [];
	let emittedCitations = false;
	const reader = res.body.getReader();
	const decoder = new TextDecoder();
	let buffer = "";

	const emitCitations = (sources: PerplexitySource[]) => {
		if (sources.length === 0) return;
		citations = sources;
		if (!emittedCitations) {
			options.onCitations?.(sources);
			emittedCitations = true;
		} else {
			options.onCitations?.(sources);
		}
	};

	for (;;) {
		const { done, value } = await reader.read();
		if (done) break;
		buffer += decoder.decode(value, { stream: true });

		let nl: number;
		while ((nl = buffer.indexOf("\n")) >= 0) {
			const line = buffer.slice(0, nl).trim();
			buffer = buffer.slice(nl + 1);
			if (!line || !line.startsWith("data:")) continue;
			const payload = line.slice(5).trim();
			if (payload === "[DONE]") continue;
			try {
				const chunk = JSON.parse(payload) as ChatCompletionChunk;
				const delta = chunk.choices?.[0]?.delta?.content;
				if (delta) {
					content += delta;
					options.onDelta?.(delta);
				}
				if (chunk.citations || chunk.search_results) {
					emitCitations(mergeSources(chunk.citations, chunk.search_results));
				}
			} catch {
				// ignore malformed keepalive / partial lines
			}
		}
	}

	return { content, citations };
}

/**
 * ResearchPanel - interactive Perplexity research TUI.
 *
 * A full-screen custom component (via ctx.ui.custom) that lets you run a
 * back-and-forth research session against the Perplexity API *outside* your
 * main pi context window. Queries and streamed answers live only in this
 * component's memory; nothing enters the session until you build a recap.
 *
 * Keys:
 *   Enter              send query (streamed answer appended to transcript)
 *   Ctrl+P             cycle Perplexity model
 *   Ctrl+T             toggle deep-research (sonar-deep-research) mode
 *   Ctrl+R             build recap from transcript (closes panel)
 *   Up / Down          scroll transcript
 *   PageUp / PageDown  scroll transcript by a page
 *   Esc                cancel a running search, or close the panel when idle
 */

import type { Theme } from "@earendil-works/pi-coding-agent";
import { getMarkdownTheme } from "@earendil-works/pi-coding-agent";
import {
	CURSOR_MARKER,
	type Component,
	type Focusable,
	Input,
	Markdown,
	matchesKey,
	visibleWidth,
	wrapTextWithAnsi,
} from "@earendil-works/pi-tui";
import type { TUI } from "@earendil-works/pi-tui";
import {
	type PerplexityMessage,
	type PerplexityModelInfo,
	type PerplexitySource,
	PERPLEXITY_MODELS,
	streamPerplexity,
} from "./perplexity.ts";

export interface TranscriptTurn {
	role: "user" | "assistant";
	text: string;
	citations?: PerplexitySource[];
}

export interface ResearchResult {
	recap: true;
	transcript: TranscriptTurn[];
	modelLabel: string;
}

export interface ResearchPanelDeps {
	/** Build a recap string from the transcript using the current pi model. */
	synthesize: (transcript: TranscriptTurn[], signal: AbortSignal) => Promise<string>;
}

const RESEARCH_SYSTEM_PROMPT =
	"You are a precise research assistant. Use search results to answer the user's question with concrete facts and cite sources. Be thorough but concise. When the user asks follow-ups, maintain context across the conversation.";

export class ResearchPanel implements Component, Focusable {
	private tui: TUI;
	private theme: Theme;
	private mdTheme: ReturnType<typeof getMarkdownTheme>;
	private deps: ResearchPanelDeps;

	private input: Input;
	private turns: TranscriptTurn[] = [];

	private modelIndex = 1; // sonar-pro by default
	private deepResearch = false;

	private status: "idle" | "searching" | "recap" | "error" = "idle";
	private statusMessage = "";

	// streaming state for the in-flight answer
	private partial = "";
	private partialCitations: PerplexitySource[] = [];
	private abortController: AbortController | null = null;

	// scroll
	private scrollOffset = 0;
	private autoScroll = true;
	private lastTranscriptHeight = 0;

	public focused = false;

	constructor(tui: TUI, theme: Theme, deps: ResearchPanelDeps) {
		this.tui = tui;
		this.theme = theme;
		this.mdTheme = getMarkdownTheme();
		this.deps = deps;
		this.input = new Input();
		this.input.onSubmit = (value) => this.submitQuery(value);
		this.input.onEscape = () => this.handleEscape();
	}

	private get model(): PerplexityModelInfo {
		if (this.deepResearch) {
			const dr = PERPLEXITY_MODELS.find((m) => m.id === "sonar-deep-research");
			if (dr) return dr;
		}
		return PERPLEXITY_MODELS[this.modelIndex];
	}

	private get transcriptHeight(): number {
		const rows = process.stdout.rows ?? 24;
		// header(1) + blank(1) + divider(1) + input(1) + help(1) = 5
		return Math.max(3, rows - 5);
	}

	invalidate(): void {
		this.input.invalidate();
	}

	handleInput(data: string): void {
		// While searching, only Esc (cancel) and scroll are allowed.
		if (this.status === "searching") {
			if (matchesKey(data, "escape")) {
				this.abortController?.abort();
				return;
			}
			if (matchesKey(data, "up") || matchesKey(data, "down")) {
				this.handleScroll(matchesKey(data, "up") ? -1 : 1);
				this.tui.requestRender();
			}
			return;
		}

		if (matchesKey(data, "escape")) {
			this.handleEscape();
			return;
		}
		if (matchesKey(data, "enter")) {
			this.submitQuery(this.input.getValue());
			return;
		}
		if (matchesKey(data, "ctrl+p")) {
			this.cycleModel();
			this.tui.requestRender();
			return;
		}
		if (matchesKey(data, "ctrl+t")) {
			this.deepResearch = !this.deepResearch;
			this.tui.requestRender();
			return;
		}
		if (matchesKey(data, "ctrl+r")) {
			void this.requestRecap();
			return;
		}
		if (matchesKey(data, "up")) {
			this.handleScroll(-1);
			this.tui.requestRender();
			return;
		}
		if (matchesKey(data, "down")) {
			this.handleScroll(1);
			this.tui.requestRender();
			return;
		}
		if (matchesKey(data, "pageup")) {
			this.handleScroll(-this.transcriptHeight);
			this.tui.requestRender();
			return;
		}
		if (matchesKey(data, "pagedown")) {
			this.handleScroll(this.transcriptHeight);
			this.tui.requestRender();
			return;
		}

		// printable / editing keys go to the input box
		this.input.handleInput(data);
		this.tui.requestRender();
	}

	private handleEscape(): void {
		if (this.status === "searching") {
			this.abortController?.abort();
			return;
		}
		// idle: close panel, discard everything
		this.done?.(null);
	}

	private handleScroll(delta: number): void {
		this.autoScroll = false;
		this.scrollOffset = Math.max(0, this.scrollOffset + delta);
	}

	private cycleModel(): void {
		const nonDeep = PERPLEXITY_MODELS.filter((m) => !m.deepResearch);
		this.modelIndex = (this.modelIndex + 1) % nonDeep.length;
		// keep modelIndex valid within the non-deep list
		const idx = nonDeep.findIndex((m) => m.id === this.model.id);
		if (idx >= 0) this.modelIndex = PERPLEXITY_MODELS.indexOf(nonDeep[idx]!);
	}

	private buildMessages(): PerplexityMessage[] {
		const messages: PerplexityMessage[] = [{ role: "system", content: RESEARCH_SYSTEM_PROMPT }];
		for (const turn of this.turns) {
			messages.push({ role: turn.role, content: turn.text });
		}
		return messages;
	}

	private async submitQuery(rawQuery: string): Promise<void> {
		const query = rawQuery.trim();
		if (!query || this.status === "searching") return;

		this.input.setValue("");
		this.turns.push({ role: "user", text: query });
		this.partial = "";
		this.partialCitations = [];
		this.status = "searching";
		this.statusMessage = `searching (${this.model.label})…`;
		this.autoScroll = true;
		this.tui.requestRender();

		this.abortController = new AbortController();
		const messages = this.buildMessages();
		const modelId = this.model.id;

		try {
			await streamPerplexity(messages, modelId, {
				signal: this.abortController.signal,
				onDelta: (chunk) => {
					this.partial += chunk;
					if (this.autoScroll) this.scrollOffset = 0;
					this.tui.requestRender();
				},
				onCitations: (sources) => {
					this.partialCitations = sources;
					this.tui.requestRender();
				},
			}).then((result) => {
				this.turns.push({
					role: "assistant",
					text: this.partial || result.content,
					citations: result.citations.length ? result.citations : this.partialCitations,
				});
			});
			this.status = "idle";
			this.statusMessage = "";
			this.partial = "";
			this.partialCitations = [];
			this.autoScroll = true;
		} catch (err) {
			if (this.abortController?.signal.aborted) {
				// keep whatever streamed so far as a partial answer
				if (this.partial.trim()) {
					this.turns.push({
						role: "assistant",
						text: this.partial + "\n\n_(search cancelled)_",
						citations: this.partialCitations,
					});
				}
				this.status = "idle";
			} else {
				this.status = "error";
				this.statusMessage = err instanceof Error ? err.message : String(err);
			}
			this.partial = "";
			this.partialCitations = [];
		} finally {
			this.abortController = null;
			this.tui.requestRender();
		}
	}

	private async requestRecap(): Promise<void> {
		if (this.turns.length === 0) {
			this.status = "error";
			this.statusMessage = "nothing to recap yet";
			this.tui.requestRender();
			return;
		}
		this.status = "recap";
		this.statusMessage = "building recap…";
		this.tui.requestRender();

		this.abortController = new AbortController();
		try {
			const recap = await this.deps.synthesize(this.turns, this.abortController.signal);
			this.done?.({ recap: true, transcript: this.turns, modelLabel: this.model.label });
			// store recap in case the caller wants to inspect (not used here)
			void recap;
		} catch (err) {
			if (this.abortController.signal.aborted) {
				this.status = "idle";
			} else {
				this.status = "error";
				this.statusMessage = err instanceof Error ? err.message : String(err);
			}
		} finally {
			this.abortController = null;
			this.tui.requestRender();
		}
	}

	// ---- rendering --------------------------------------------------------

	private renderQuery(turn: TranscriptTurn, width: number): string[] {
		const prefix = this.theme.fg("accent", this.theme.bold("❯ "));
		const wrapped = wrapTextWithAnsi(prefix + turn.text, width);
		return wrapped;
	}

	private renderAnswer(text: string, citations: PerplexitySource[] | undefined, width: number): string[] {
		const md = new Markdown(text || "_(no answer)_", 0, 0, this.mdTheme);
		let lines = md.render(width);

		if (citations && citations.length > 0) {
			lines.push(this.theme.fg("dim", "─".repeat(Math.min(width, 48))));
			const srcLines: string[] = [];
			citations.forEach((c, i) => {
				const num = this.theme.fg("accent", `[${i + 1}]`);
				const title = this.theme.fg("muted", c.title);
				const url = this.theme.fg("dim", c.url);
				srcLines.push(`${num} ${title} ${url}`);
			});
			lines.push(...srcLines);
		}
		return lines;
	}

	private renderTranscript(width: number): string[] {
		const lines: string[] = [];
		for (const turn of this.turns) {
			if (turn.role === "user") {
				lines.push(...this.renderQuery(turn, width));
			} else {
				lines.push(...this.renderAnswer(turn.text, turn.citations, width));
			}
			lines.push("");
		}

		// in-flight streaming answer
		if (this.partial || this.status === "searching") {
			lines.push(...this.renderAnswer(this.partial || "…", this.partialCitations, width));
		}

		if (this.status === "error" && this.statusMessage) {
			lines.push(this.theme.fg("error", `Error: ${this.statusMessage}`));
			lines.push("");
		}

		return lines;
	}

	render(width: number): string[] {
		const innerWidth = Math.max(10, width - 2);

		// header
		const model = this.model;
		const modeTag = this.deepResearch
			? this.theme.fg("warning", "deep-research")
			: this.theme.fg("dim", model.label);
		const statusTag =
			this.status === "searching"
				? this.theme.fg("warning", ` ${this.statusMessage}`)
				: this.status === "recap"
					? this.theme.fg("accent", ` ${this.statusMessage}`)
					: this.status === "error"
						? this.theme.fg("error", " error")
						: "";
		const header =
			this.theme.fg("toolTitle", this.theme.bold(" Perplexity Research ")) +
			this.theme.fg("dim", " · ") +
			modeTag +
			statusTag;
		const headerLine = header + " ".repeat(Math.max(0, innerWidth - visibleWidth(header)));

		// transcript (scrollable slice)
		const allLines = this.renderTranscript(innerWidth);
		const th = this.transcriptHeight;
		this.lastTranscriptHeight = th;

		// if user scrolled up, keep offset; else pin to bottom
		let start: number;
		if (this.autoScroll || allLines.length <= th) {
			start = Math.max(0, allLines.length - th);
			this.scrollOffset = 0;
		} else {
			const maxStart = Math.max(0, allLines.length - th);
			start = Math.min(maxStart, Math.max(0, maxStart - this.scrollOffset));
		}
		const visible = allLines.slice(start, start + th);
		// pad to fill the transcript area so input stays pinned at the bottom
		while (visible.length < th) visible.push("");

		// scroll indicator
		const scrollInfo =
			allLines.length > th
				? this.theme.fg("dim", ` ${start + 1}-${Math.min(start + th, allLines.length)}/${allLines.length} `)
				: "";
		const divider = this.theme.fg("border", "─".repeat(innerWidth)) + scrollInfo;

		// input line
		const prompt = this.theme.fg("accent", "▸ ");
		const inputWidth = Math.max(4, innerWidth - visibleWidth(prompt));
		const renderedInput = this.input.render(inputWidth);
		// Render Input already includes CURSOR_MARKER when focused; prepend prompt.
		const inputLine =
			prompt +
			(renderedInput[0] ?? "") +
			CURSOR_MARKER.slice(0, 0); // keep marker passthrough (Input emits its own)

		// help line
		const help = this.theme.fg(
			"dim",
			" ⏎ send · ctrl+p model · ctrl+t deep-research · ctrl+r recap · ↑↓ scroll · esc close",
		);

		const out: string[] = [];
		out.push(headerLine);
